from pathlib import Path
import base64,re

TILES={
'grass.webp':'',
'road_corner_ne.webp':'',
'road_corner_se.webp':'',
'road_corner_sw.webp':'',
'road_cross.webp':'',
'road_straight_h.webp':'',
'road_straight_v.webp':'',
'road_t_n.webp':''
}
out=Path('assets/maptiles'); out.mkdir(parents=True,exist_ok=True)
for name,b64 in TILES.items(): (out/name).write_bytes(base64.b64decode(b64))

p=Path('index.html'); s=p.read_text(encoding='utf-8')
s=re.sub(r'<title>GRIMPATH v[^<]+</title>','<title>GRIMPATH v0.16</title>',s,count=1)
marker="const TILE={EMPTY:'empty',ENEMY:'enemy',CHEST:'chest',WEAPON:'weapon',SUPPORT:'support',SHRINE:'shrine',BOSS:'boss',ROCK:'rock',SMITH:'smith'};"
source_js="""\nconst MAP_TILE_SOURCES={grass:'assets/maptiles/grass.webp',roadStraightH:'assets/maptiles/road_straight_h.webp',roadStraightV:'assets/maptiles/road_straight_v.webp',roadCornerNW:'assets/maptiles/road_corner_ne.webp',roadCornerSE:'assets/maptiles/road_corner_se.webp',roadCornerSW:'assets/maptiles/road_corner_sw.webp',roadCross:'assets/maptiles/road_cross.webp',roadTMissingS:'assets/maptiles/road_t_n.webp'};\nconst MAP_SPRITES={};function loadMapSprites(){const e=Object.entries(MAP_TILE_SOURCES);let n=0;e.forEach(([k,src])=>{const i=new Image();i.onload=i.onerror=()=>{n++;if(n===e.length)renderAll()};i.src=src;MAP_SPRITES[k]=i})}\n"""
if 'const MAP_TILE_SOURCES=' not in s: s=s.replace(marker,marker+source_js)
new_map=r'''function roadMaskAt(x,y){const rows=game.world.tiles,c=(nx,ny)=>!!rows[ny]?.[nx]?.road;return(c(x,y-1)?1:0)|(c(x+1,y)?2:0)|(c(x,y+1)?4:0)|(c(x-1,y)?8:0)}
function drawSpriteRotated(ctx,img,x,y,size,rot=0){if(!img||!img.complete||!img.naturalWidth)return false;ctx.save();ctx.translate(x+size/2,y+size/2);if(rot)ctx.rotate(rot*Math.PI/180);ctx.drawImage(img,-size/2,-size/2,size,size);ctx.restore();return true}
function drawGrassCell(ctx,x,y,size){if(drawSpriteRotated(ctx,MAP_SPRITES.grass,x,y,size))return;ctx.fillStyle='#344b36';ctx.fillRect(x,y,size,size)}
function drawRoadCell(ctx,x,y,size,m){if(m===15&&drawSpriteRotated(ctx,MAP_SPRITES.roadCross,x,y,size))return;if(m===11&&drawSpriteRotated(ctx,MAP_SPRITES.roadTMissingS,x,y,size))return;if(m===7&&drawSpriteRotated(ctx,MAP_SPRITES.roadTMissingS,x,y,size,90))return;if(m===14&&drawSpriteRotated(ctx,MAP_SPRITES.roadTMissingS,x,y,size,180))return;if(m===13&&drawSpriteRotated(ctx,MAP_SPRITES.roadTMissingS,x,y,size,270))return;if((m===5||m===1||m===4)&&drawSpriteRotated(ctx,MAP_SPRITES.roadStraightV,x,y,size))return;if((m===10||m===2||m===8)&&drawSpriteRotated(ctx,MAP_SPRITES.roadStraightH,x,y,size))return;if(m===9&&drawSpriteRotated(ctx,MAP_SPRITES.roadCornerNW,x,y,size))return;if(m===3&&drawSpriteRotated(ctx,MAP_SPRITES.roadCornerSW,x,y,size,180))return;if(m===6&&drawSpriteRotated(ctx,MAP_SPRITES.roadCornerSE,x,y,size))return;if(m===12&&drawSpriteRotated(ctx,MAP_SPRITES.roadCornerSW,x,y,size))return;drawGrassCell(ctx,x,y,size)}
function renderMap(){const canvas=$('#worldCanvas');if(!canvas)return;const ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,N=game.world.size,cell=W/N,pal=worldPalette();ctx.clearRect(0,0,W,H);for(const row of game.world.tiles)for(const t of row)drawGrassCell(ctx,t.x*cell,t.y*cell,cell+.5);for(const row of game.world.tiles)for(const t of row)if(t.road)drawRoadCell(ctx,t.x*cell,t.y*cell,cell+.5,roadMaskAt(t.x,t.y));for(const row of game.world.tiles)for(const t of row){const cx=(t.x+.5)*cell,cy=(t.y+.5)*cell;if(t.type===TILE.ROCK)drawRock(ctx,cx,cy+2,.9)}for(const row of game.world.tiles)for(const t of row){if(t.type===TILE.EMPTY||t.type===TILE.ROCK||t.cleared)continue;drawPoi(ctx,t.type,(t.x+.5)*cell,(t.y+.5)*cell,t.type===TILE.BOSS?24:20)}const px=(game.pos.x+.5)*cell,py=(game.pos.y+.5)*cell;ctx.save();ctx.translate(px,py);ctx.shadowColor='rgba(244,201,113,.65)';ctx.shadowBlur=20;ctx.fillStyle='#d7b36a';ctx.strokeStyle='#201b13';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowColor='transparent';ctx.fillStyle='#262d27';ctx.beginPath();ctx.moveTo(-9,10);ctx.lineTo(0,-14);ctx.lineTo(9,10);ctx.closePath();ctx.fill();ctx.fillStyle='#f0d7a2';ctx.beginPath();ctx.arc(0,-6,4,0,Math.PI*2);ctx.fill();ctx.restore();const radius=game.visionRadius();for(const row of game.world.tiles)for(const t of row){const near=Math.max(Math.abs(t.x-game.pos.x),Math.abs(t.y-game.pos.y))<=radius,visible=t.revealed&&(!game.isNight()||near);if(!visible){ctx.fillStyle=pal.fog;ctx.fillRect(t.x*cell,t.y*cell,cell+.5,cell+.5)}}if(game.isNight()){const ng=ctx.createRadialGradient(px,py,cell*.55,px,py,cell*(radius+1.3));ng.addColorStop(0,'rgba(12,18,15,0)');ng.addColorStop(.62,'rgba(5,8,7,.2)');ng.addColorStop(1,'rgba(2,4,3,.62)');ctx.fillStyle=ng;ctx.fillRect(0,0,W,H)}const vg=ctx.createRadialGradient(W/2,H/2,W*.28,W/2,H/2,W*.7);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(0,0,0,.42)');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H)}

function weaponHtml'''
s,n=re.subn(r'function renderMap\(\)\{.*?\n\}\n\nfunction weaponHtml',new_map,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'renderMap patch failed: {n}')
s=s.replace('hydrateIcons();renderAll();','hydrateIcons();loadMapSprites();renderAll();')
p.write_text(s,encoding='utf-8')
print('v0.16 migration complete')
